import{_ as t,o as l,c as o,a2 as r}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"🎮 04 · 强化学习 RL","description":"","frontmatter":{},"headers":[],"relativePath":"04-算法岗-传统深度学习/04-强化学习RL.md","filePath":"04-算法岗-传统深度学习/04-强化学习RL.md","lastUpdated":1786806808000}'),e={name:"04-算法岗-传统深度学习/04-强化学习RL.md"};function i(n,a,s,c,d,h){return l(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="🎮-04-·-强化学习-rl" tabindex="-1">🎮 04 · 强化学习 RL <a class="header-anchor" href="#🎮-04-·-强化学习-rl" aria-label="Permalink to &quot;🎮 04 · 强化学习 RL&quot;">​</a></h1><blockquote><p>从 AlphaGo 到 RLHF，RL 是「智能体与环境交互学最优策略」的范式。大模型对齐（PPO/DPO/GRPO）都建立其上。</p></blockquote><hr><h2 id="一、核心概念-mdp" tabindex="-1">一、核心概念（MDP） <a class="header-anchor" href="#一、核心概念-mdp" aria-label="Permalink to &quot;一、核心概念（MDP）&quot;">​</a></h2><ul><li><strong>状态 s、动作 a、奖励 r、策略 π、价值 V/Q</strong></li><li><strong>回报</strong>：累积折扣奖励 $G_t = \\sum \\gamma^k r_{t+k}$</li><li><strong>Bellman 方程</strong>：价值的递归关系，RL 算法基石</li></ul><h2 id="二、价值-vs-策略方法" tabindex="-1">二、价值 vs 策略方法 <a class="header-anchor" href="#二、价值-vs-策略方法" aria-label="Permalink to &quot;二、价值 vs 策略方法&quot;">​</a></h2><ul><li><strong>价值基</strong>：学 Q/V，再导出策略（Q-learning / DQN）</li><li><strong>策略梯度</strong>：直接优化策略参数 $\\nabla J = \\mathbb{E}[\\nabla\\log\\pi(a|s) \\cdot A]$ <ul><li>REINFORCE（基础 PG）</li><li><strong>Actor-Critic</strong>：Actor 出动作，Critic 评价值，降低方差</li></ul></li><li><strong>PPO</strong>（Proximal Policy Optimization）：用「裁剪」限制策略更新幅度，稳定高效 —— RLHF 主力</li><li><strong>GRPO</strong>：组相对策略优化，省 value 网络（见 <code>01-LLM/05-对齐</code>）</li></ul><h2 id="三、探索与利用" tabindex="-1">三、探索与利用 <a class="header-anchor" href="#三、探索与利用" aria-label="Permalink to &quot;三、探索与利用&quot;">​</a></h2><ul><li>ε-greedy、熵正则、噪声网络</li><li>平衡「试新动作」与「用已知好动作」</li></ul><h2 id="四、与大模型的关系" tabindex="-1">四、与大模型的关系 <a class="header-anchor" href="#四、与大模型的关系" aria-label="Permalink to &quot;四、与大模型的关系&quot;">​</a></h2><ul><li>RLHF 把「人类偏好」当奖励，用 PPO 优化语言策略</li><li>RLVR（可验证奖励）用「答案对错/单测通过」当奖励，训推理模型（DeepSeek-R1）</li><li>离线 RL、DPO 等新范式降低对在线交互的依赖</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：PG 和 Q-learning 区别？</strong></p><blockquote><p>PG 直接优化策略（连续动作友好）；Q-learning 学价值再贪心选（离散为主）。Actor-Critic 结合两者。</p></blockquote><p><strong>Q2：为什么 PPO 比普通 PG 稳？</strong></p><blockquote><p>PPO 用 ratio 裁剪限制单步更新幅度，避免策略突变导致训练崩溃，样本效率与稳定性兼顾。</p></blockquote><p><strong>Q3：RLHF 里奖励从哪来？</strong></p><blockquote><p>来自奖励模型 RM（人类偏好训练）；或用可验证奖励（RLVR）直接给对错信号，省 RM。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-大数据挖掘">05-大数据挖掘</a></p>',20)])])}const P=t(e,[["render",i]]);export{p as __pageData,P as default};
